  const ls = { get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }, set(k, v) { try { if (v == null) localStorage.removeItem(k); else localStorage.setItem(k, v); } catch (e) { /* sem armazenamento */ } } };
  function inicial() {
    let q = null; try { q = new URLSearchParams(location.search).get('lang'); } catch (e) { /* navegador antigo */ }
    if (q && LANGS.includes(q)) { ls.set('ea-lang', q); return q; }
    const s = ls.get('ea-lang'); if (s && LANGS.includes(s)) return s;
    const n = String(navigator.language || 'pt').slice(0, 2).toLowerCase();
    return LANGS.includes(n) ? n : 'en';
  }
  let lang = inicial(), ix = LANGS.indexOf(lang), nf = {};

  const t = (k, v) => {
    const e = S[k]; let s = e ? (e[ix] != null ? e[ix] : e[0]) : k;
    if (v) s = s.replace(/\{(\w+)\}/g, (m, n) => (v[n] != null ? v[n] : m));
    return s;
  };
  const num = (v, d = 0) => {
    if (v == null || !isFinite(v)) return '—';
    if (Math.abs(v) < 0.5 * Math.pow(10, -d)) v = 0;
    return (nf[d] || (nf[d] = new Intl.NumberFormat(LOC[lang], { minimumFractionDigits: d, maximumFractionDigits: d }))).format(v);
  };
  const pct = (v, d = 0) => (v == null || !isFinite(v)) ? '—' : num(v * 100, d) + '%';
  const emMil = u => /mil|thousand|\bk\b/i.test(u || '');
  /* valor monetário compacto: 3,00 mi · 187 mil (PT); 3.00 M · 187 k (EN) */
  function money(v, u, longo) {
    if (v == null || !isFinite(v)) return '—';
    const suf = longo ? ' ' + u : '';
    if (emMil(u)) return num(v, Math.abs(v) >= 1000 ? 0 : 1) + suf;
    const a = Math.abs(v);
    if (a >= 1e6) return num(v / 1e6, 2) + ' ' + t('u.mi') + suf;
    if (a >= 1e4) return num(v / 1e3, 0) + ' ' + t('u.mil') + suf;
    return num(v, 0) + suf;
  }
  /* nomes dos dados: a chave é o texto em português */
  const nm = (tab, k, j) => { const e = N[tab] && N[tab][k]; return e && ix > 0 ? (e[(j || 0) + ix - 1] || k) : k; };
